1	package com.maritime.platform.gateway.autoconfigure;
2	
3	import org.springframework.boot.autoconfigure.AutoConfiguration;
4	import org.springframework.boot.autoconfigure.condition.ConditionalOnBean;
5	import org.springframework.boot.autoconfigure.condition.ConditionalOnClass;
6	import org.springframework.context.annotation.Bean;
7	import org.springframework.data.redis.connection.ReactiveRedisConnectionFactory;
8	import org.springframework.data.redis.core.ReactiveRedisTemplate;
9	import org.springframework.data.redis.serializer.RedisSerializationContext;
10	import org.springframework.data.redis.serializer.StringRedisSerializer;
11	
12	/**
13	 * Provides a {@link ReactiveRedisTemplate} with String serialization
14	 * for simple key/value Redis operations used in gateway state checks.
15	 */
16	@AutoConfiguration
17	@ConditionalOnClass(ReactiveRedisConnectionFactory.class)
18	public class GatewayRedisConfiguration {
19	
20		@Bean
21		@ConditionalOnBean(ReactiveRedisConnectionFactory.class)
22		ReactiveRedisTemplate<String, String> reactiveStringRedisTemplate(
23				ReactiveRedisConnectionFactory connectionFactory) {
24			RedisSerializationContext<String, String> context = RedisSerializationContext
25					.<String, String>newSerializationContext(StringRedisSerializer.UTF_8)
26					.key(StringRedisSerializer.UTF_8)
27					.value(StringRedisSerializer.UTF_8)
28					.hashKey(StringRedisSerializer.UTF_8)
29					.hashValue(StringRedisSerializer.UTF_8)
30					.build();
31			return new ReactiveRedisTemplate<>(connectionFactory, context);
32		}
33	}
