3	import com.maritime.platform.gateway.error.GatewayErrorWriter;
4	import com.maritime.platform.gateway.security.AuthMode;
5	import com.maritime.platform.gateway.security.GatewayPrincipal;
6	import com.maritime.platform.gateway.security.RouteSecurityPolicy;
7	import com.maritime.platform.gateway.security.jwt.GatewayAuthErrorCode;
8	import com.maritime.platform.gateway.security.jwt.JwtAuthenticationException;
9	import com.maritime.platform.gateway.security.jwt.JwtAuthenticationManager;
10	
11	import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
12	import org.springframework.cloud.gateway.filter.GatewayFilterChain;
13	import org.springframework.cloud.gateway.filter.GlobalFilter;
14	import org.springframework.core.Ordered;
15	import org.springframework.core.annotation.Order;
16	import org.springframework.stereotype.Component;
17	import org.springframework.web.server.ServerWebExchange;
18	
19	import reactor.core.publisher.Mono;
20	
21	/**
22	 * Extracts and validates a JWT Bearer token for routes that require
23	 * JWT authentication. Stores the mapped {@link GatewayPrincipal.User}
24	 * in the exchange for downstream filters and handlers.
25	 */
26	@Component
27	@ConditionalOnProperty("maritime.gateway.security.jwt.enabled")
28	@Order(GatewayFilterOrder.JWT_AUTHENTICATION)
29	public class JwtAuthenticationGatewayFilter implements GlobalFilter, Ordered {
30	
31		private final JwtAuthenticationManager authManager;
32		private final GatewayErrorWriter errorWriter;
33	
34		public JwtAuthenticationGatewayFilter(JwtAuthenticationManager authManager,
35				GatewayErrorWriter errorWriter) {
36			this.authManager = authManager;
37			this.errorWriter = errorWriter;
38		}
39	
40		@Override
41		public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
42			RouteSecurityPolicy policy = exchange.getAttribute(RouteSecurityPolicyFilter.POLICY_ATTR);
43			if (policy == null) {
44				return chain.filter(exchange);
45			}
46	
47			AuthMode mode = policy.getAuthMode();
48	
49			if (mode == AuthMode.JWT_AND_HMAC) {
50				return errorWriter.write(exchange, GatewayAuthErrorCode.UNSUPPORTED_AUTH_MODE);
51			}
52	
53			if (mode != AuthMode.JWT && mode != AuthMode.JWT_OR_HMAC) {
54				return chain.filter(exchange);
55			}
56	
57			String token = extractBearerToken(exchange);
58	
59			// JWT_OR_HMAC: only require JWT when Bearer token is present;
60			// without a Bearer token, pass through to let HMAC handle it.
61			if (mode == AuthMode.JWT_OR_HMAC && (token == null || token.isEmpty())) {
62				return chain.filter(exchange);
63			}
64	
65			if (token == null || token.isEmpty()) {
66				return errorWriter.write(exchange, GatewayAuthErrorCode.MISSING_TOKEN);
67			}
68	
69			return authManager.authenticate(token)
70					.flatMap(principal -> {
71						exchange.getAttributes().put(GatewayPrincipal.ATTRIBUTE, principal);
72						return chain.filter(exchange);
73					})
74					.onErrorResume(JwtAuthenticationException.class,
75							e -> errorWriter.write(exchange, e.getErrorCode()));
76		}
77	
78		@Override
79		public int getOrder() {
80			return GatewayFilterOrder.JWT_AUTHENTICATION;
81		}
82	
83		private String extractBearerToken(ServerWebExchange exchange) {
84			String auth = exchange.getRequest().getHeaders().getFirst("Authorization");
85			if (auth != null && auth.startsWith("Bearer ")) {
86				return auth.substring(7).trim();
87			}
88			return null;
89		}
90	}
