1	package com.maritime.platform.gateway.error;
2	
3	import com.maritime.platform.gateway.filter.TraceIdGatewayFilter;
4	import org.springframework.http.HttpStatus;
5	import org.springframework.http.MediaType;
6	import org.springframework.web.server.ServerWebExchange;
7	import reactor.core.publisher.Mono;
8	
9	import java.nio.charset.StandardCharsets;
10	
11	/**
12	 * Default implementation of {@link GatewayErrorWriter}.
13	 * <p>
14	 * Produces JSON responses in the form
15	 * {@code {"code":401,"message":"MISSING_TOKEN","data":null}}.
16	 * The response includes an {@code X-Trace-Id} header when available.
17	 */
18	public class DefaultGatewayErrorWriter implements GatewayErrorWriter {
19	
20		@Override
21		public Mono<Void> write(ServerWebExchange exchange, String errorCode) {
22			HttpStatus status = resolveStatus(errorCode);
23			exchange.getResponse().setStatusCode(status);
24			exchange.getResponse().getHeaders().setContentType(MediaType.APPLICATION_JSON);
25	
26			String traceId = exchange.getAttribute(TraceIdGatewayFilter.TRACE_ID_ATTR);
27			if (traceId != null) {
28				exchange.getResponse().getHeaders().set(TraceIdGatewayFilter.TRACE_ID_HEADER, traceId);
29			}
30	
31			String body = String.format("{\"code\":%d,\"message\":\"%s\",\"data\":null}",
32					status.value(), escapeJson(errorCode));
33			byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
34			return exchange.getResponse()
35					.writeWith(Mono.just(exchange.getResponse().bufferFactory().wrap(bytes)));
36		}
37	
38		private HttpStatus resolveStatus(String errorCode) {
39			if ("FORBIDDEN".equals(errorCode)) {
40				return HttpStatus.FORBIDDEN;
41			}
42			if ("UNSUPPORTED_AUTH_MODE".equals(errorCode)) {
43				return HttpStatus.NOT_IMPLEMENTED;
44			}
45			return HttpStatus.UNAUTHORIZED;
46		}
47	
48		private static String escapeJson(String s) {
49			if (s == null) {
50				return "";
51			}
52			return s.replace("\\", "\\\\")
53					.replace("\"", "\\\"")
54					.replace("\n", "\\n")
55					.replace("\r", "\\r")
56					.replace("\t", "\\t");
57		}
58	}
