1	package com.maritime.platform.gateway.filter;
2	
3	import com.maritime.platform.gateway.error.GatewayErrorWriter;
4	import com.maritime.platform.gateway.security.AuthMode;
5	import com.maritime.platform.gateway.security.GatewayPrincipal;
6	import com.maritime.platform.gateway.security.GatewaySecurityProperties;
7	import com.maritime.platform.gateway.security.RouteSecurityPolicy;
8	import com.maritime.platform.gateway.security.jwt.GatewayAuthErrorCode;
9	import com.maritime.platform.gateway.security.jwt.JwtAuthenticationException;
10	import com.maritime.platform.gateway.security.nonce.JwtNonceValidator;
11	
12	import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
13	import org.springframework.cloud.gateway.filter.GatewayFilterChain;
14	import org.springframework.cloud.gateway.filter.GlobalFilter;
15	import org.springframework.core.Ordered;
16	import org.springframework.core.annotation.Order;
17	import org.springframework.stereotype.Component;
18	import org.springframework.web.server.ServerWebExchange;
19	
20	import reactor.core.publisher.Mono;
21	
22	/**
23	 * Enforces JWT nonce validation for write requests on JWT-protected routes.
24	 * <p>
25	 * Runs after {@link JwtAuthenticationGatewayFilter} so the authenticated
26	 * principal is available. Only enforces nonce for HTTP methods configured
27	 * in {@code maritime.gateway.security.jwt.nonce.required-methods}
28	 * (default: POST, PUT, PATCH, DELETE).
29	 */
30	@Component
31	@ConditionalOnProperty("maritime.gateway.security.jwt.enabled")
32	@Order(GatewayFilterOrder.JWT_NONCE)
33	public class JwtNonceGatewayFilter implements GlobalFilter, Ordered {
34	
35		private final JwtNonceValidator nonceValidator;
36		private final GatewaySecurityProperties properties;
37		private final GatewayErrorWriter errorWriter;
38	
39		public JwtNonceGatewayFilter(JwtNonceValidator nonceValidator,
40				GatewaySecurityProperties properties, GatewayErrorWriter errorWriter) {
41			this.nonceValidator = nonceValidator;
42			this.properties = properties;
43			this.errorWriter = errorWriter;
44		}
45	
46		@Override
47		public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
48			if (!properties.getJwt().getNonce().isEnabled()) {
49				return chain.filter(exchange);
50			}
51	
52			RouteSecurityPolicy policy = exchange.getAttribute(RouteSecurityPolicyFilter.POLICY_ATTR);
53			if (!requiresJwt(policy)) {
54				return chain.filter(exchange);
55			}
56	
57			String method = exchange.getRequest().getMethod().name();
58			if (!properties.getJwt().getNonce().getRequiredMethods().contains(method)) {
59				return chain.filter(exchange);
60			}
61	
62			GatewayPrincipal.User principal = exchange.getAttribute(GatewayPrincipal.ATTRIBUTE);
63			if (principal == null) {
64				return chain.filter(exchange);
65			}
66	
67			String nonce = exchange.getRequest().getHeaders().getFirst("X-Nonce");
68			if (nonce == null || nonce.isEmpty()) {
69				return errorWriter.write(exchange, GatewayAuthErrorCode.NONCE_REQUIRED);
70			}
71	
72			return nonceValidator.validate(principal.sessionId(), nonce)
73					.then(chain.filter(exchange))
74					.onErrorResume(JwtAuthenticationException.class,
75							e -> errorWriter.write(exchange, e.getErrorCode()));
76		}
77	
78		@Override
79		public int getOrder() {
80			return GatewayFilterOrder.JWT_NONCE;
81		}
82	
83		private boolean requiresJwt(RouteSecurityPolicy policy) {
84			if (policy == null) {
85				return false;
86			}
87			AuthMode mode = policy.getAuthMode();
88			return mode == AuthMode.JWT || mode == AuthMode.JWT_OR_HMAC || mode == AuthMode.JWT_AND_HMAC;
89		}
90	}
