22	/**
23	 * Extracts, decrypts, verifies and maps JWT tokens to
24	 * {@link GatewayPrincipal.User} instances.
25	 *
26	 * <p>All CPU-bound operations run via {@link Mono#fromCallable},
27	 * keeping the non-blocking gateway event loop free. State validation
28	 * (session, blacklist, user-enabled) is delegated to
29	 * {@link JwtStateValidator} and runs reactively.
30	 */
31	@Component
32	@ConditionalOnProperty("maritime.gateway.security.jwt.enabled")
33	public class JwtAuthenticationManager {
34	
35		private final GatewaySecurityProperties.Jwt jwtConfig;
36		private final SecretKey signingKey;
37		private final JwtEncryptor encryptor;
38		private final JwtClaimsMapper claimsMapper;
39		private final Clock clock;
40		private final JwtStateValidator stateValidator;
41	
42		@Autowired
43		public JwtAuthenticationManager(GatewaySecurityProperties properties, JwtClaimsMapper claimsMapper) {
44			this(properties, claimsMapper, Clock.systemUTC(), null);
45		}
46	
47		public JwtAuthenticationManager(GatewaySecurityProperties properties, JwtClaimsMapper claimsMapper,
48				JwtStateValidator stateValidator) {
49			this(properties, claimsMapper, Clock.systemUTC(), stateValidator);
50		}
51	
52		JwtAuthenticationManager(GatewaySecurityProperties properties, JwtClaimsMapper claimsMapper, Clock clock) {
53			this(properties, claimsMapper, clock, null);
54		}
55	
56		JwtAuthenticationManager(GatewaySecurityProperties properties, JwtClaimsMapper claimsMapper, Clock clock,
57				JwtStateValidator stateValidator) {
58			this.jwtConfig = properties.getJwt();
59			this.signingKey = Keys.hmacShaKeyFor(jwtConfig.getSecret().getBytes(StandardCharsets.UTF_8));
60			this.encryptor = jwtConfig.isEncrypted() ? new JwtEncryptor(jwtConfig.getSecret()) : null;
61			this.claimsMapper = claimsMapper;
62			this.clock = clock;
63			this.stateValidator = stateValidator;
64		}
65	
66		/**
67		 * Authenticate the given token string, returning a mapped user principal
68		 * or an error signal carrying a {@link JwtAuthenticationException}.
69		 */
70		public Mono<GatewayPrincipal.User> authenticate(String token) {
71			return Mono.fromCallable(() -> doParseAndMap(token))
72					.flatMap(result -> {
73						if (stateValidator == null) {
74							return Mono.just(result.user);
75						}
76						return stateValidator.validate(result.user.sessionId(), result.jti, result.user.userId())
77								.thenReturn(result.user);
78					});
79		}
80	
81		private AuthResult doParseAndMap(String token) {
82			String rawToken = decryptIfNeeded(token);
83			Claims claims = parseAndValidate(rawToken);
84			GatewayPrincipal.User user = claimsMapper.map(claims);
85			validateRequiredClaims(user);
86			String jti = claims.getId();
87			return new AuthResult(user, jti);
88		}
89	
90		private String decryptIfNeeded(String token) {
91			if (encryptor == null) {
92				return token;
93			}
94			String decrypted = encryptor.decrypt(token);
95			if (decrypted == null) {
96				throw new JwtAuthenticationException(GatewayAuthErrorCode.INVALID_TOKEN,
97						"Token decryption failed");
98			}
99			return decrypted;
100		}
101	
102		private Claims parseAndValidate(String token) {
103			try {
104				Jws<Claims> jws = Jwts.parser()
105						.verifyWith(signingKey)
106						.clockSkewSeconds(jwtConfig.getClockSkewSeconds())
107						.clock(() -> Date.from(clock.instant()))
108						.build()
109						.parseSignedClaims(token);
110	
111				Claims claims = jws.getPayload();
112	
113				String issuer = claims.getIssuer();
114				if (!jwtConfig.getIssuer().equals(issuer)) {
115					throw new JwtAuthenticationException(GatewayAuthErrorCode.INVALID_TOKEN,
116							"Invalid issuer: " + issuer);
117				}
118	
119				Date expiration = claims.getExpiration();
120				if (expiration != null) {
121					Instant expiryInstant = expiration.toInstant();
122					Instant threshold = clock.instant().minusSeconds(jwtConfig.getClockSkewSeconds());
123					if (expiryInstant.isBefore(threshold)) {
124						throw new JwtAuthenticationException(GatewayAuthErrorCode.TOKEN_EXPIRED,
125								"Token expired at " + expiration);
126					}
127				}
128	
129				return claims;
130			} catch (ExpiredJwtException e) {
131				throw new JwtAuthenticationException(GatewayAuthErrorCode.TOKEN_EXPIRED, e.getMessage());
132			} catch (JwtAuthenticationException e) {
133				throw e;
134			} catch (Exception e) {
135				throw new JwtAuthenticationException(GatewayAuthErrorCode.INVALID_TOKEN, e.getMessage());
136			}
137		}
138	
139		private void validateRequiredClaims(GatewayPrincipal.User user) {
140			if (!StringUtils.hasText(user.userId())) {
141				throw new JwtAuthenticationException(GatewayAuthErrorCode.INVALID_TOKEN,
142						"Required claim '" + jwtConfig.getClaims().getUserId() + "' is missing or empty");
143			}
144			if (!StringUtils.hasText(user.sessionId())) {
145				throw new JwtAuthenticationException(GatewayAuthErrorCode.INVALID_TOKEN,
146						"Required claim '" + jwtConfig.getClaims().getSessionId() + "' is missing or empty");
147			}
148		}
149	
150		/**
151		 * Intermediate result holding the mapped user and the JWT ID for
152		 * downstream state validation.
153		 */
154		private static class AuthResult {
155			final GatewayPrincipal.User user;
156			final String jti;
157	
158			AuthResult(GatewayPrincipal.User user, String jti) {
159				this.user = user;
160				this.jti = jti;
161			}
162		}
163	}
