34	
35		public String build(String appKey, String method, String rawPath, String rawQuery,
36				String timestamp, String nonce, String bodyDigest) {
37			StringBuilder sb = new StringBuilder(512);
38			sb.append(appKey).append(LF);
39			sb.append(method.toUpperCase()).append(LF);
40			sb.append(rawPath != null ? rawPath : "").append(LF);
41			sb.append(canonicalizeQuery(rawQuery)).append(LF);
42			sb.append(timestamp).append(LF);
43			sb.append(nonce).append(LF);
44			sb.append(bodyDigest);
45			return sb.toString();
46		}
47	
48		String canonicalizeQuery(String rawQuery) {
49			if (rawQuery == null || rawQuery.isEmpty()) {
50				return "";
51			}
52			Map<String, String[]> params = new LinkedHashMap<>();
53			for (String pair : rawQuery.split("&")) {
54				int idx = pair.indexOf('=');
55				String key;
56				String value;
57				if (idx >= 0) {
58					key = decode(pair.substring(0, idx));
59					value = decode(pair.substring(idx + 1));
60				} else {
61					key = decode(pair);
62					value = "";
63				}
64				params.merge(key, new String[]{value}, (existing, incoming) -> {
65					String[] merged = Arrays.copyOf(existing, existing.length + 1);
66					merged[existing.length] = incoming[0];
67					return merged;
68				});
69			}
70			return params.entrySet().stream()
71					.sorted(Map.Entry.comparingByKey())
72					.flatMap(e -> Arrays.stream(e.getValue())
73							.map(v -> encode(e.getKey()) + "=" + encode(v)))
74					.collect(Collectors.joining("&"));
75		}
76	
77		private static String decode(String s) {
78			return URLDecoder.decode(s, StandardCharsets.UTF_8);
79		}
80	
81		private static String encode(String s) {
82			return URLEncoder.encode(s, StandardCharsets.UTF_8).replace("+", "%20");
83		}
84	}
