7	import org.springframework.beans.factory.annotation.Autowired;
8	import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean;
9	import org.springframework.data.redis.core.ReactiveRedisTemplate;
10	import org.springframework.stereotype.Component;
11	
12	import reactor.core.publisher.Mono;
13	
14	import java.util.Arrays;
15	import java.util.Collections;
16	import java.util.List;
17	import java.util.Map;
18	
19	/**
20	 * Default {@link AppCredentialResolver} that reads from a Redis hash
21	 * and falls back to configuration-based apps when Redis has no entry.
22	 *
23	 * <p>Redis key pattern: {@code {redisKeyPrefix}{appKey}} (default {@code iam:app:auth:{appKey}}).
24	 * Hash field names are configurable via {@code maritime.gateway.security.hmac.credentials.fields.*}.
25	 *
26	 * <p>Override by declaring a custom {@link AppCredentialResolver} bean.
27	 */
28	@Component
29	@ConditionalOnMissingBean(AppCredentialResolver.class)
30	public class DefaultAppCredentialResolver implements AppCredentialResolver {
31	
32		private final GatewaySecurityProperties properties;
33		private final ReactiveRedisTemplate<String, String> redisTemplate;
34	
35		public DefaultAppCredentialResolver(GatewaySecurityProperties properties,
36				@Autowired(required = false) ReactiveRedisTemplate<String, String> redisTemplate) {
37			this.properties = properties;
38			this.redisTemplate = redisTemplate;
39		}
40	
41		@Override
42		public Mono<AppCredential> resolve(String appKey) {
43			if (redisTemplate != null) {
44				return resolveFromRedis(appKey)
45						.switchIfEmpty(Mono.defer(() -> resolveFromConfig(appKey)));
46			}
47			return resolveFromConfig(appKey);
48		}
49	
50		private Mono<AppCredential> resolveFromRedis(String appKey) {
51			GatewaySecurityProperties.Credentials credentials = properties.getHmac().getCredentials();
52			String redisKey = credentials.getRedisKeyPrefix() + appKey;
53	
54			return redisTemplate.<String, String>opsForHash()
55					.entries(redisKey)
56					.collectMap(Map.Entry::getKey, Map.Entry::getValue)
57					.flatMap(entries -> {
58						if (entries.isEmpty()) {
59							return Mono.empty();
60						}
61						return mapToCredential(appKey, entries);
62					});
63		}
64	
65		private Mono<AppCredential> mapToCredential(String appKey, Map<String, String> entries) {
66			GatewaySecurityProperties.CredentialFields fields = properties.getHmac().getCredentials().getFields();
67			String enabledTrueValue = fields.getEnabledTrueValue();
68	
69			String enabledStr = entries.getOrDefault(fields.getEnabled(), enabledTrueValue);
70			boolean enabled = enabledTrueValue.equalsIgnoreCase(enabledStr)
71					|| "1".equals(enabledStr);
72	
73			if (!enabled) {
74				return Mono.error(new JwtAuthenticationException(
75						GatewayAuthErrorCode.APP_DISABLED,
76						"App is disabled: " + appKey));
77			}
78	
79			String permissionsStr = entries.getOrDefault(fields.getPermissions(), "");
80			List<String> permissions = permissionsStr.isBlank()
81					? List.of()
82					: Arrays.asList(permissionsStr.split(","));
83	
84			AppCredential credential = AppCredential.builder()
85					.appKey(appKey)
86					.appSecret(entries.get(fields.getAppSecret()))
87					.appCode(entries.get(fields.getAppCode()))
88					.appId(entries.get(fields.getAppId()))
89					.tenantId(entries.get(fields.getTenantId()))
90					.tenantCode(entries.get(fields.getTenantCode()))
91					.permissions(permissions)
92					.enabled(enabled)
93					.build();
94	
95			return Mono.just(credential);
96		}
97	
98		private Mono<AppCredential> resolveFromConfig(String appKey) {
99			for (GatewaySecurityProperties.ConfigApp app : properties.getHmac().getCredentials().getApps()) {
100				if (app.getAppKey().equals(appKey)) {
101					if (!app.isEnabled()) {
102						return Mono.error(new JwtAuthenticationException(
103								GatewayAuthErrorCode.APP_DISABLED,
104								"App is disabled: " + appKey));
105					}
106					AppCredential credential = AppCredential.builder()
107							.appKey(appKey)
108							.appSecret(app.getAppSecret())
109							.appCode(app.getAppCode())
110							.enabled(true)
111							.build();
112					return Mono.just(credential);
113				}
114			}
115			return Mono.error(new JwtAuthenticationException(
116					GatewayAuthErrorCode.UNKNOWN_APP,
117					"Unknown app key: " + appKey));
118		}
119	}
