28		private static void addRoute(GatewaySecurityProperties props, String id,
29		                             List<String> paths, List<String> methods, AuthMode mode) {
30			GatewaySecurityProperties.RoutePolicy rp = new GatewaySecurityProperties.RoutePolicy();
31			rp.setId(id);
32			rp.setPaths(paths);
33			if (methods != null) {
34				rp.setMethods(methods);
35			}
36			rp.setAuthMode(mode);
37			props.getRoutes().add(rp);
38		}
39	
40		private RouteSecurityPolicy resolve(GatewaySecurityProperties props, String path, String method) {
41			RouteSecurityPolicyResolver resolver = new RouteSecurityPolicyResolver(props);
42			resolver.afterPropertiesSet();
43			return resolver.resolve(path, method);
44		}
45	
46		private RouteSecurityPolicy resolveWithCustomizers(GatewaySecurityProperties props,
47		                                                   String path, String method,
48		                                                   List<GatewaySecurityPolicyCustomizer> customizers) {
49			RouteSecurityPolicyResolver resolver = new RouteSecurityPolicyResolver(props, customizers);
50			resolver.afterPropertiesSet();
51			return resolver.resolve(path, method);
52		}
